        "hook": "一个小小的捏捏乐，宁波海关监管出境货值1.47亿元，比上年同期多了10.33倍——工厂订单排到一个月以后。",
        "story": {
          "setup": "海关总署11月10日数据里有个反差：1至10月机电产品出口增25.2%，服装玩具家具这类劳动密集型产品只增2.4%。可捏捏乐这个小品类，宁波海关统计年初至10月底出境货值1.47亿元，同比多出10.33倍。",
          "conflict": "订单节奏全变了。过去外贸讲大客户、大批量、按季度排产，一张单做几个月；现在买家几万件起步，紧接着追单、改色、换款，英美客户每一两周就加急一次，交期从按月算压到按周算。",
          "turn": "产业带接得住：宁波周边从原料、模具到包装，开车个把钟头配齐；义乌保留大量熟练手工，脆皮款蜡层靠工人一层层刷。有位做了四年的工厂主，九成订单来自海外，车间每天出一两万个，排期一个月后。",
          "open": "他的打法就一条：每月上新十几款，分一次性和可反复玩两条线，绝不押单一爆款。价格账更扎眼——国内批发3.2到5元，亚马逊美国站卖7到20美元，差价大头在品牌和渠道；义乌有人把DIY材料包放TikTok，三个月近3万单、约555万元。"
        },
