            "text": "这类团最要命的地方在节奏。老人被从熟悉的生活里拽出来，一路上听的是\"最后一批名额\"\"海景房以后要涨\"，看到的是低得不像真的房价，等回到本地冷静下来时，已经太晚了。那些看起来最热情的人，其实都和房子有关。"
