            "text": "那位老人交出去的41万，是他养老钱里的一大半；回家的路上，他大概会反复算这笔账，却算不出一个结果。至于那笔钱后来有没有要回来，报道里没有交代。这件事真正该被问起的，是那些带他去看房的人。"
